// Ownership and page positions belong to a character; sets reference the same items.
const INVENTORY_PAGE_SIZE=45;let inventorySelected=null,inventoryPage=0,inventoryDrag=null;
function normalizeInventories(d){const valid=new Set(d.items.map(i=>i.id)),claimed=new Set();for(const c of d.characters){const seen=new Set();c.inventory=(Array.isArray(c.inventory)?c.inventory:[]).slice(0,4500).map(id=>{if(typeof id!=='string'||!valid.has(id)||seen.has(id))return null;seen.add(id);claimed.add(id);return id;});for(const id of c.sets.flatMap(s=>Object.values(s.items)))if(valid.has(id)&&!seen.has(id)){c.inventory.push(id);seen.add(id);claimed.add(id);}c.inventoryPages=Math.max(4,Math.min(100,Number.isInteger(c.inventoryPages)?c.inventoryPages:4),Math.ceil(c.inventory.length/45));}const first=d.characters[0];for(const it of d.items)if(!claimed.has(it.id)){const empty=first.inventory.indexOf(null);if(empty>=0)first.inventory[empty]=it.id;else first.inventory.push(it.id);}}
function ownsInventoryItem(id,c=char()){return c.inventory?.includes(id)&&!!item(id);}
function inventoryEquipped(id){return Object.values(set().items).includes(id);}
function addInventoryReference(id,position){if(!item(id))return;const c=char();c.inventory??=[];if(c.inventory.includes(id))return;if(Number.isInteger(position)&&position>=0&&!c.inventory[position])c.inventory[position]=id;else{let empty=c.inventory.findIndex(x=>!x);if(empty>=0)c.inventory[empty]=id;else c.inventory.push(id);}}
function equipInventoryItem(id,slot){const it=item(id);if(!char().sets.length||!ownsInventoryItem(id)||!it||it.slot!==slot||![...slots,...extra].some(e=>e[0]===slot)){toast('Este item só pode ser equipado no seu slot correspondente.');return false;}const previous=set().items[slot];if(previous===id)return true;const from=char().inventory.indexOf(id),old=char().inventory.indexOf(previous);if(previous){if(old>=0)char().inventory[old]=id;else char().inventory.push(id);char().inventory[from]=previous;}set().items[slot]=id;inventorySelected=null;hideTooltip();save();return true;}
function moveInventoryItem(id,index){if(!ownsInventoryItem(id)||!Number.isInteger(index)||index<0||index>=4500)return false;const c=char(),from=c.inventory.indexOf(id),other=c.inventory[index];if(inventoryEquipped(id)){if(other&&!inventoryEquipped(other)){if(item(other)?.slot===item(id)?.slot)return equipInventoryItem(other,item(id).slot);toast('Escolhe uma célula vazia para desequipar.');return false;}delete set().items[item(id).slot];}c.inventory[from]=other||null;c.inventory[index]=id;c.inventoryPages=Math.max(c.inventoryPages,Math.floor(index/45)+1);inventorySelected=null;hideTooltip();save();return true;}
function deleteInventoryItem(id){if(readonly||!ownsInventoryItem(id))return;for(const c of data.characters){c.inventory=c.inventory?.map(x=>x===id?null:x)||[];for(const s of c.sets)for(const k of Object.keys(s.items))if(s.items[k]===id)delete s.items[k];}data.items=data.items.filter(x=>x.id!==id);inventorySelected=null;}
function renderInventory(){const host=$('#inventory');if(!host)return;const c=char();if(inventorySelected?.character!==c.id||!ownsInventoryItem(inventorySelected?.id))inventorySelected=null;const pages=Math.max(4,c.inventoryPages,Math.ceil(c.inventory.length/45));inventoryPage=Math.max(0,Math.min(inventoryPage,pages-1));const selected=item(inventorySelected?.id);host.innerHTML=`<div class="inventory-pages" role="group" aria-label="Páginas do inventário">${Array.from({length:pages},(_,i)=>`<button data-inventory-page="${i}" aria-pressed="${i===inventoryPage}">${i+1}</button>`).join('')}${!readonly&&pages<100?'<button data-inventory-add-page aria-label="Adicionar página">+</button>':''}</div><div class="inventory-grid">${Array.from({length:45},(_,i)=>{const index=inventoryPage*45+i,id=c.inventory[index],it=id&&!inventoryEquipped(id)?item(id):null;return `<button class="inventory-cell ${it?'filled':''} ${selected&&selected.id===it?.id?'selected':''}" data-inventory-cell="${index}" ${it?`data-inventory-item="${esc(it.id)}" draggable="true"`:''} aria-label="${esc(it?it.name+' '+itemUpgrade(it):'Célula vazia '+(index+1))}">${it?equipmentIcon(it,it.slot):''}${it?`<b class="upgrade">${esc(itemUpgrade(it))}</b>`:''}</button>`;}).join('')}</div><p class="hint">${readonly?'Podes experimentar trocas nesta vista; não altera o perfil publicado.':'Arrasta para equipar ou trocar. Arrasta uma peça equipada para uma célula vazia para a retirar.'} Toca num item para ver os atributos e equipar.</p>${selected?`<div class="inventory-inspector">${bonusContent(selected)}<div class="inventory-item-actions"><button data-inventory-equip="${esc(selected.id)}" ${!c.sets.length?'disabled':''}>Equipar / trocar</button>${!readonly?`<button data-inventory-edit="${esc(selected.id)}">Editar</button><button class="danger" data-inventory-delete="${esc(selected.id)}">Eliminar</button>`:''}<button data-inventory-close>Fechar</button></div></div>`:''}`;for(const b of document.querySelectorAll('[data-slot]'))b.draggable=!!item(set().items[b.dataset.slot]);}
function newInventoryItem(position){if(readonly)return;open('Adicionar ao inventário',selectPairs('inventorySlot','Tipo de equipamento','weapon',[...slots,...extra].map(([k,n])=>[k,n])),v=>{queueMicrotask(()=>editSlot(v.inventorySlot,{inventory:true,position}));});}
document.addEventListener('click',e=>{const b=e.target.closest?.('button');if(!b)return;if(inventorySelected&&b.dataset.slot){e.stopImmediatePropagation();equipInventoryItem(inventorySelected.id,b.dataset.slot);return;}if(b.dataset.inventoryItem){e.stopImmediatePropagation();hideTooltip();inventorySelected={character:char().id,id:b.dataset.inventoryItem};renderInventory();return;}if(b.dataset.inventoryCell!==undefined&&!readonly){e.stopImmediatePropagation();newInventoryItem(Number(b.dataset.inventoryCell));return;}if(b.id==='addInventoryItem')newInventoryItem();if(b.dataset.inventoryPage!==undefined){inventoryPage=Number(b.dataset.inventoryPage);renderInventory();}if(b.hasAttribute('data-inventory-add-page')&&!readonly){char().inventoryPages++;inventoryPage=char().inventoryPages-1;save();}if(b.dataset.inventoryEquip)equipInventoryItem(b.dataset.inventoryEquip,item(b.dataset.inventoryEquip)?.slot);if(b.dataset.inventoryEdit&&!readonly)editSlot(item(b.dataset.inventoryEdit).slot,{inventory:true,id:b.dataset.inventoryEdit});if(b.dataset.inventoryDelete&&!readonly&&confirm('Eliminar este item do inventário e de todos os sets que o usam?')){deleteInventoryItem(b.dataset.inventoryDelete);save();}if(b.hasAttribute('data-inventory-close')){inventorySelected=null;renderInventory();}},true);
document.addEventListener('dragstart',e=>{const b=e.target.closest?.('[data-inventory-item],[data-slot]'),id=b?.dataset.inventoryItem||set().items[b?.dataset.slot];if(!b||!ownsInventoryItem(id)){e.preventDefault();return;}inventoryDrag={id,character:char().id};hideTooltip();e.dataTransfer?.setData('application/x-armory-item',id);if(e.dataTransfer)e.dataTransfer.effectAllowed='move';document.body.classList.add('inventory-dragging');});
document.addEventListener('dragover',e=>{if(!inventoryDrag||inventoryDrag.character!==char().id)return;const b=e.target.closest?.('[data-slot],[data-inventory-cell],[data-inventory-page]');if(!b)return;e.preventDefault();if(e.dataTransfer)e.dataTransfer.dropEffect='move';});
document.addEventListener('drop',e=>{const drag=inventoryDrag;inventoryDrag=null;document.body.classList.remove('inventory-dragging');if(!drag||drag.character!==char().id)return;const b=e.target.closest?.('[data-slot],[data-inventory-cell],[data-inventory-page]');if(!b)return;e.preventDefault();if(b.dataset.slot)equipInventoryItem(drag.id,b.dataset.slot);else if(b.dataset.inventoryCell!==undefined)moveInventoryItem(drag.id,Number(b.dataset.inventoryCell));else if(b.dataset.inventoryPage!==undefined){inventoryPage=Number(b.dataset.inventoryPage);renderInventory();const empty=Array.from({length:45},(_,i)=>inventoryPage*45+i).find(i=>!char().inventory[i]||inventoryEquipped(char().inventory[i]));if(empty!==undefined)moveInventoryItem(drag.id,empty);else toast('Esta página está cheia.');}});
document.addEventListener('dragend',()=>{inventoryDrag=null;document.body.classList.remove('inventory-dragging');});
